={
  "from": "Homeward Alerts <alerts@REPLACE_WITH_YOUR_VERIFIED_DOMAIN>",
  "to": ["{{ $json.caregiverEmail }}"],
  "subject": "Check-in reminder for {{ $json.patientName || $json.recoveryCode }}",
  "html": "<p>Hi,</p><p>We wanted to let you know that <strong>{{ $json.patientName || 'your patient (recovery code ' + $json.recoveryCode + ')' }}</strong> hasn't checked in with Homeward in about <strong>{{ Math.floor($json.hoursSinceLastActivity / 24) }} days</strong>.</p><p>{{ $json.neverCheckedIn ? "They haven't submitted a check-in since their recovery plan was created." : "Their last recorded activity was a " + ($json.lastActivityType === 'checkin' ? 'full check-in' : 'quick \\"I\'m okay\\" update') + "." }}</p><p>This doesn't necessarily mean anything is wrong — they may just be busy. But it might be worth giving them a quick call or message to check in.</p><p style=\"color:#666; font-size:13px;\">Recovery code: {{ $json.recoveryCode }}</p><p>— Homeward</p>"
}
